/// <summary>
/// SysOperation and <c>Global::runAsync</c> processor for <c>UTCSFCustomerPushQueue</c>.
/// Supports both immediate non-blocking real-time pushes via <c>runAsync</c> (with duplicate coalescing)
/// and scheduled recurring SysOperation batch sweeps (supporting up to 200 customers per API call).
/// </summary>
public class UTCSFCustomerPushBatchService extends SysOperationServiceBase
{
    private const str TargetCompanyId          = 'utc';
    private const int MaxCustomersPerBatchCall = 200;

}

Method.Source:
/// <summary>
/// Entry point for the SysOperation batch job to process pending records in <c>UTCSFCustomerPushQueue</c>.
/// </summary>
/// <param name = "_contract">Data contract specifying batch limits and API chunk size (1..200).</param>
public void processQueue(UTCSFCustomerPushBatchContract _contract)
{
    int maxRecords = (_contract != null && _contract.parmMaxRecordsToProcess() > 0)
        ? _contract.parmMaxRecordsToProcess()
        : 500;

    int batchSize = (_contract != null && _contract.parmBatchSizePerApiCall() > 1)
        ? min(_contract.parmBatchSizePerApiCall(), MaxCustomersPerBatchCall)
        : 1;

    boolean requeueFailed = (_contract != null) ? _contract.parmIncludeFailedForRetry() : false;

    changecompany(TargetCompanyId)
    {
        UTCSFIntegrationParameters parameters = UTCSFIntegrationParameters::find();
        if (parameters.IsEnabled == NoYes::No)
        {
            info('Salesforce Customer Push integration is currently disabled in parameters.');
            return;
        }

        if (requeueFailed)
        {
            this.resetEligibleFailedRecords();
        }

        // Recover any queue items stranded in Processing state after an AOS recycle or crash
        UTCSFCustomerPushQueue::recoverStaleProcessingRecords(15);

        UTCSFCustomerPushService pushService = UTCSFCustomerPushService::construct();

        try
        {
            UTCSFCustomerPushQueue queueCandidate;
            Map                    latestRecIdByCustomer = new Map(Types::String, Types::Int64);
            Set                    outOfScopeCustomers   = new Set(Types::String);
            List                   supersededRecIds      = new List(Types::Int64);
            int                    selectedCount         = 0;

            while select RecId, CustAccount, AllowOutOfScopeGroup from queueCandidate
                order by CreatedDateTime asc, RecId asc
                where queueCandidate.Status == UTCSFCustomerPushStatus::Pending
            {
                if (queueCandidate.AllowOutOfScopeGroup == NoYes::Yes)
                {
                    outOfScopeCustomers.add(queueCandidate.CustAccount);
                }

                if (latestRecIdByCustomer.exists(queueCandidate.CustAccount))
                {
                    supersededRecIds.addEnd(latestRecIdByCustomer.lookup(queueCandidate.CustAccount));
                }

                latestRecIdByCustomer.insert(queueCandidate.CustAccount, queueCandidate.RecId);
                selectedCount++;

                if (selectedCount >= maxRecords)
                {
                    break;
                }
            }

            // Mark superseded pending duplicates as Succeeded (coalesced) so only one push runs per customer
            ListEnumerator supersededEnum = supersededRecIds.getEnumerator();
            while (supersededEnum.moveNext())
            {
                RecId supersededRecId = supersededEnum.current();
                if (UTCSFCustomerPushQueue::markProcessing(supersededRecId))
                {
                    UTCSFCustomerPushQueue::markSucceeded(supersededRecId, 'COALESCED', '');
                }
            }

            int           succeededCount = 0;
            int           failedCount    = 0;
            MapEnumerator enumerator     = latestRecIdByCustomer.getEnumerator();

            if (batchSize <= 1)
            {
                while (enumerator.moveNext())
                {
                    str   custAccount = enumerator.currentKey();
                    RecId queueRecId  = enumerator.currentValue();

                    if (UTCSFCustomerPushQueue::markProcessing(queueRecId))
                    {
                        UTCSFCustomerPushQueue activeRecord = UTCSFCustomerPushQueue::findByRecId(queueRecId);
                        if (outOfScopeCustomers.in(custAccount) && activeRecord.AllowOutOfScopeGroup == NoYes::No)
                        {
                            activeRecord = this.promoteAllowOutOfScopeFlag(queueRecId);
                        }

                        if (pushService.pushCustomer(activeRecord))
                        {
                            succeededCount++;
                        }
                        else
                        {
                            failedCount++;
                        }
                    }
                }
            }
            else
            {
                List currentChunk     = new List(Types::Record);
                int  currentChunkSize = 0;

                while (enumerator.moveNext())
                {
                    str   custAccount = enumerator.currentKey();
                    RecId queueRecId  = enumerator.currentValue();

                    if (UTCSFCustomerPushQueue::markProcessing(queueRecId))
                    {
                        UTCSFCustomerPushQueue activeRecord = UTCSFCustomerPushQueue::findByRecId(queueRecId);
                        if (outOfScopeCustomers.in(custAccount) && activeRecord.AllowOutOfScopeGroup == NoYes::No)
                        {
                            activeRecord = this.promoteAllowOutOfScopeFlag(queueRecId);
                        }

                        currentChunk.addEnd(activeRecord);
                        currentChunkSize++;

                        if (currentChunkSize >= batchSize)
                        {
                            int chunkSucceeded;
                            int chunkFailed;
                            [chunkSucceeded, chunkFailed] = pushService.pushCustomerBatch(currentChunk);
                            succeededCount += chunkSucceeded;
                            failedCount    += chunkFailed;

                            currentChunk     = new List(Types::Record);
                            currentChunkSize = 0;
                        }
                    }
                }

                if (currentChunkSize > 0)
                {
                    int chunkSucceeded;
                    int chunkFailed;
                    [chunkSucceeded, chunkFailed] = pushService.pushCustomerBatch(currentChunk);
                    succeededCount += chunkSucceeded;
                    failedCount    += chunkFailed;
                }
            }

            info(strFmt(
                'UTC Salesforce Customer Push completed. Succeeded: %1, Failed: %2.',
                succeededCount,
                failedCount));
        }
        finally
        {
            pushService.dispose();
        }
    }
}

private UTCSFCustomerPushQueue promoteAllowOutOfScopeFlag(RecId _queueRecId)
{
    UTCSFCustomerPushQueue queueRecord;

    ttsbegin;
    queueRecord = UTCSFCustomerPushQueue::findByRecId(_queueRecId, true);
    if (queueRecord.RecId != 0 && queueRecord.AllowOutOfScopeGroup == NoYes::No)
    {
        queueRecord.AllowOutOfScopeGroup = NoYes::Yes;
        queueRecord.update();
    }
    ttscommit;

    return queueRecord;
}

/// <summary>
/// Resets transient Failed queue items back to Pending while excluding permanent validation errors
/// (HTTP 400 or Salesforce v1.6 row <c>status: "error"</c>).
/// </summary>
private void resetEligibleFailedRecords()
{
    UTCSFCustomerPushQueue queueRecord;

    ttsbegin;

    while select forupdate queueRecord
        where queueRecord.Status             == UTCSFCustomerPushStatus::Failed
           && queueRecord.IsPermanentFailure == NoYes::No
           && !(queueRecord.LastError like 'HTTP 400*')
    {
        queueRecord.Status     = UTCSFCustomerPushStatus::Pending;
        queueRecord.RetryCount = 0;
        queueRecord.update();
    }

    ttscommit;
}

/// <summary>
/// Static asynchronous worker method invoked via <c>Global::runAsync</c> immediately after a database commit.
/// Coalesces rapid multi-datasource saves on the same customer to avoid concurrent Salesforce record locks.
/// </summary>
/// <param name = "_params">Container holding <c>[RecId queueRecId]</c>.</param>
/// <param name = "_cancellationToken">Cancellation token supplied by the async runtime.</param>
/// <returns>Container holding <c>[boolean isSuccess]</c>.</returns>
public static container processQueueItemAsync(
    container                          _params,
    System.Threading.CancellationToken _cancellationToken)
{
    if (conLen(_params) < 1)
    {
        return [false];
    }

    RecId   queueRecId = conPeek(_params, 1);
    boolean isSuccess  = false;

    if (!queueRecId)
    {
        return [false];
    }

    changecompany(TargetCompanyId)
    {
        if (UTCSFCustomerPushQueue::markProcessing(queueRecId))
        {
            UTCSFCustomerPushQueue queueRecord = UTCSFCustomerPushQueue::findByRecId(queueRecId);

            // If a newer Pending row already exists for the same customer (e.g. rapid form saves across
            // DirPersonName, LogisticsElectronicAddress, and CustTable), coalesce this older item.
            UTCSFCustomerPushQueue newerPending;
            select firstonly RecId from newerPending
                index CustAccountStatusIdx
                where newerPending.CustAccount == queueRecord.CustAccount
                   && newerPending.Status      == UTCSFCustomerPushStatus::Pending
                   && newerPending.RecId       >  queueRecord.RecId;

            if (newerPending.RecId != 0)
            {
                if (queueRecord.AllowOutOfScopeGroup == NoYes::Yes)
                {
                    ttsbegin;
                    UTCSFCustomerPushQueue newerForUpdate = UTCSFCustomerPushQueue::findByRecId(newerPending.RecId, true);
                    if (newerForUpdate.RecId != 0 && newerForUpdate.AllowOutOfScopeGroup == NoYes::No)
                    {
                        newerForUpdate.AllowOutOfScopeGroup = NoYes::Yes;
                        newerForUpdate.update();
                    }
                    ttscommit;
                }

                UTCSFCustomerPushQueue::markSucceeded(queueRecId, 'COALESCED', '');
                return [true];
            }

            UTCSFCustomerPushService pushService = UTCSFCustomerPushService::construct();

            try
            {
                isSuccess = pushService.pushCustomer(queueRecord);
            }
            finally
            {
                pushService.dispose();
            }
        }
    }

    return [isSuccess];
}

/// <summary>
/// Dispatches an asynchronous background execution via <c>Global::runAsync</c> for the specified queue item.
/// Safe to call from both interactive client sessions and non-interactive/batch sessions.
/// </summary>
/// <param name = "_queueRecId">The <c>RecId</c> of the <c>UTCSFCustomerPushQueue</c> record.</param>
public static void triggerImmediateAsyncPush(RecId _queueRecId)
{
    if (!_queueRecId)
    {
        return;
    }

    try
    {
        Global::runAsync(
            classNum(UTCSFCustomerPushBatchService),
            staticMethodStr(UTCSFCustomerPushBatchService, processQueueItemAsync),
            [_queueRecId],
            System.Threading.CancellationToken::None);
    }
    catch
    {
        // If Global::runAsync is unavailable in a non-GUI/OData context, the record remains Pending
        // in UTCSFCustomerPushQueue and is picked up by the recurring SysOperation batch job.
        exceptionTextFallThrough();
    }
}
